def differs_by_one(a, b):
    if len(a) != len(b):
        return False
    diff = sum(1 for x, y in zip(a, b) if x != y)
    return diff == 1

def ladder_length_brute(begin_word, end_word, word_list):
    if end_word not in word_list:
        return 0
    word_set = set(word_list)
    queue = [begin_word]
    word_set.discard(begin_word)
    level = 1
    while queue:
        next_queue = []
        for word in queue:
            if word == end_word:
                return level
            for other in list(word_set):                        # compare against EVERY remaining word
                if differs_by_one(word, other):
                    next_queue.append(other)
                    word_set.discard(other)
        queue = next_queue
        level += 1
    return 0

